{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO annual allowable rent increase","requirement":"For RSO-covered units, rent may be raised once every 12 months by the allowable rent increase percentage. Since February 2, 2026, a landlord may no longer include an extra percentage increase for utilities.","key_value":"Once every 12 months at the allowable rent increase percentage","coverage_conditions":"Rental properties first built on or before October 1, 1978, plus replacement units under LAMC Section 151.28, including apartments, condos, duplexes, ADUs, mobile homes and certain hotel rooms.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"replacement units under LAMC Section 151.28"},"exemptions":"Condo and townhome tenancies that commenced after December 31, 1995 (rent amount not regulated); luxury units qualifying for the RSO luxury exemption.","penalty":null,"effective_date":"2026-02-02","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage (click here to view the allowable rent increase PDF). Effective February 2, 2026, the landlord can no longer include an additional percentage increase for utilities.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction and relocation","requirement":"Landlords of RSO units may terminate a tenancy only for the listed at-fault or no-fault reasons, must give the required written notice, and must file termination notices with LAHD. No-fault evictions require tenant relocation assistance.","key_value":"No-fault evictions require relocation assistance; 30- and 60-day notice (some 120-day or 1-year)","coverage_conditions":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance, including properties first built on or before October 1, 1978.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
